mk("u07-02", "bus-income-statement", "bars", "From revenue to profit for the year",
   "Each line takes something away: cost of sales gives gross profit, expenses give operating profit, interest gives profit before tax and tax gives profit for the year. Only £52,500 of every £500,000 of sales is left.",
   "Waterfall from revenue £500,000 down to profit for the year £52,500 through cost of sales, operating expenses, finance costs and tax.",
   ["Revenue starts at £500,000.", "Cost of sales of £300,000 leaves gross profit of £200,000.", "Operating expenses of £120,000 leave operating profit of £80,000.", "Finance costs of £10,000 leave profit before tax of £70,000.", "Tax of £17,500 (25%) leaves profit for the year of £52,500."],
   terms=["Revenue", "Cost of sales", "gross profit", "Operating expenses", "operating profit", "Finance costs", "profit before tax", "Tax", "profit for the year"],
   kind="waterfall", prefix="£", suffix="k", range=[0, 560],
   items=[
     {"id": "revenue", "label": "Revenue", "v": 500, "type": "start"},
     {"id": "cost_of_sales", "label": "Cost of sales", "short": "Cost", "v": -300, "type": "delta"},
     {"id": "gross_profit", "label": "Gross profit", "short": "Gross", "v": 200, "type": "total"},
     {"id": "opex", "label": "Operating expenses", "short": "Exp.", "v": -120, "type": "delta"},
     {"id": "operating_profit", "label": "Operating profit", "short": "Op. profit", "v": 80, "type": "total"},
     {"id": "finance", "label": "Finance costs", "short": "Fin.", "v": -10, "type": "delta"},
     {"id": "pbt", "label": "Profit before tax", "short": "Pre-tax", "v": 70, "type": "total"},
     {"id": "tax", "label": "Tax at 25%", "short": "Tax", "v": -17.5, "type": "delta"},
     {"id": "profit", "label": "Profit for the year", "short": "Profit", "v": 52.5, "type": "total"}],
   relations=[
     {"expr": "revenue + cost_of_sales", "equals": "gross_profit", "name": "revenue − cost of sales = gross profit"},
     {"expr": "pbt * 0.25 * -1", "equals": "tax", "name": "tax is 25% of profit before tax"},
     {"expr": "profit / revenue", "equals": "0.105", "name": "profit for the year is 10.5% of revenue"}])

mk("u07-08", "bus-break-even", "graph", "Break-even: where revenue meets total cost",
   "Each unit sells for £50 against £30 of variable cost, so it adds £20 of contribution. Total cost starts at the £60,000 of fixed costs; the lines cross at 3,000 units. At the budgeted 4,000 units the gap is the £20,000 profit.",
   "Graph of revenue and total cost against units sold. They cross at 3,000 units and £150,000; at 4,000 units revenue is £200,000 and total cost £180,000.",
   ["Revenue is £50 a unit, a line from the origin.", "Total cost is £60,000 fixed plus £30 a unit.", "The lines meet at 3,000 units, £150,000: the break-even point.", "Budgeted sales of 4,000 units are 1,000 units above break-even, the margin of safety, and earn £20,000 profit."],
   terms=["Fixed costs", "break-even", "Contribution per unit", "margin of safety", "£60,000", "3,000 units", "4,000 units"],
   range={"x": [0, 5000], "y": [0, 260]}, ticks=[[1000, 2000, 3000, 4000, 5000], [50, 100, 150, 200, 250]], grid=[1000, 50],
   axisLabels=["units sold", "£ thousand"], xLabelBelow=True, labelHalo=True,
   curves=[{"expr": "0.05*x", "colour": "a1", "label": "Revenue", "labelAt": [4250, 238]},
           {"expr": "60+0.03*x", "colour": "a2", "label": "Total cost", "labelAt": [4150, 170]},
           {"expr": "60", "colour": "a3", "dash": "6 5", "label": "Fixed costs £60k", "labelAt": [2200, 72]}],
   points=[{"x": 3000, "y": 150, "label": "Break-even", "colour": "ink", "dx": -14, "dy": -22, "anchor": "end"}],
   marks=[{"x": 3000, "to": 150}, {"x": 4000, "label": "Budget 4,000", "to": 236, "dx": -62}],
   bands=[{"x": [3000, 4000], "label": "margin of safety", "colour": "a4"}],
   checks=[{"type": "intersect", "a": "0.05*x", "b": "60+0.03*x", "x": 3000, "y": 150, "name": "revenue equals total cost at 3,000 units (£150,000)"},
           {"type": "value", "expr": "0.05*x-(60+0.03*x)", "x": 4000, "between": [20, 20], "name": "profit at 4,000 units is £20,000"},
           {"type": "slope", "expr": "0.05*x-(0.03*x)", "x": 100, "value": 0.02, "name": "contribution is £20 a unit (price £50 less variable cost £30)"}],)

mk("u07-12", "bus-cash-forecast", "bars", "Three-month cash flow forecast",
   "Cash is counted when it moves. March's new machine takes payments to £31,000, more than the receipts and the opening balance, so the forecast shows an overdraft of £2,000 in time to arrange one.",
   "Columns of opening balance, receipts, payments and closing balance for January, February and March; closing balance £7,000, £9,000 and −£2,000.",
   ["January: £5,000 opening, £20,000 receipts, £18,000 payments, £7,000 closing.", "February: £7,000 opening, £20,000 receipts, £18,000 payments, £9,000 closing.", "March: £9,000 opening, £20,000 receipts, £31,000 payments including a machine, −£2,000 closing."],
   terms=["opening balance", "Receipts", "Payments", "Closing balance", "overdraft", "£31,000"],
   kind="columns", prefix="£", suffix="k", range=[-6, 36],
   series=[{"name": "Receipts", "colour": "good"}, {"name": "Payments", "colour": "bad"}, {"name": "Closing balance", "colour": "a1"}],
   categories=[
     {"label": "January", "short": "Jan", "values": [{"id": "r1", "v": 20}, {"id": "p1", "v": 18}, {"id": "c1", "v": 7}]},
     {"label": "February", "short": "Feb", "values": [{"id": "r2", "v": 20}, {"id": "p2", "v": 18}, {"id": "c2", "v": 9}]},
     {"label": "March", "short": "Mar", "values": [{"id": "r3", "v": 20}, {"id": "p3", "v": 31}, {"id": "c3", "v": -2}]}],
   vars0={"open1": 5},
   relations=[{"expr": "5 + r1 - p1", "equals": "c1", "name": "January closing = 5 + 20 − 18"},
              {"expr": "c1 + r2 - p2", "equals": "c2", "name": "February closing = January closing + receipts − payments"},
              {"expr": "c2 + r3 - p3", "equals": "c3", "name": "March closing = 9 + 20 − 31 = −2"}])

mk("u07-03", "bus-balance-sheet", "bars", "The statement of financial position balances",
   "Everything the business has was paid for by owners or by creditors, so assets always equal equity plus liabilities. Equity is what is left: £400,000 − £200,000 = £200,000.",
   "Two stacked columns of £400,000: assets (non-current £250,000, current £150,000) and equity £200,000 plus liabilities (non-current £100,000, current £100,000).",
   ["Assets: non-current £250,000 and current £150,000, total £400,000.", "Liabilities: current £100,000 and non-current £100,000, total £200,000.", "Equity: £400,000 − £200,000 = £200,000.", "The two columns are the same height: assets = equity + liabilities."],
   terms=["Non-current assets", "current assets", "Current liabilities", "non-current liabilities", "Equity", "assets = equity + liabilities", "£250,000", "£200,000"],
   kind="stacked", prefix="£", suffix="k", range=[0, 470],
   stacks=[{"label": "Assets", "parts": [{"id": "nca", "label": "Non-current assets", "v": 250, "colour": "a1"}, {"id": "ca", "label": "Current assets", "v": 150, "colour": "a4"}]},
           {"label": "Equity + liabilities", "parts": [{"id": "equity", "label": "Equity", "v": 200, "colour": "good"}, {"id": "ncl", "label": "Non-current liabilities", "v": 100, "colour": "a3"}, {"id": "cl", "label": "Current liabilities", "v": 100, "colour": "a2"}]}],
   relations=[{"expr": "nca + ca", "equals": "equity + ncl + cl", "name": "assets = equity + liabilities"},
              {"expr": "nca + ca - ncl - cl", "equals": "equity", "name": "equity = assets − liabilities = £200,000"},
              {"expr": "nca + ca", "equals": "400", "name": "total assets are £400,000"}])

mk("u07-11", "bus-materials-variance", "bars", "Materials variances: price and usage",
   "Cheaper material gave a favourable price variance of £420, but 100 kg more was used than standard, an adverse usage variance of £500. Net, the materials cost £80 more than standard.",
   "Waterfall: price variance +£420 favourable, usage variance −£500 adverse, net materials variance −£80 adverse.",
   ["Price variance: (5.00 − 4.80) × 2,100 = £420 favourable.", "Usage variance: (2,000 − 2,100) × 5 = £500 adverse.", "Net materials variance £80 adverse."],
   terms=["Price variance", "Usage variance", "£420 F", "£500 A", "£80 A", "favourable", "adverse"],
   kind="waterfall", prefix="£", range=[-160, 520],
   items=[{"id": "price", "label": "Price variance (F)", "short": "Price (F)", "v": 420, "type": "delta"},
          {"id": "usage", "label": "Usage variance (A)", "short": "Usage (A)", "v": -500, "type": "delta"},
          {"id": "net", "label": "Net variance (A)", "short": "Net (A)", "v": -80, "type": "total"}],
   relations=[{"expr": "(5 - 4.8) * 2100", "equals": "price", "name": "price variance = (5.00 − 4.80) × 2,100 = £420"},
              {"expr": "(2000 - 2100) * 5", "equals": "usage", "name": "usage variance = (2,000 − 2,100) × 5 = −£500"},
              {"expr": "4.8 * 2100", "equals": "10080", "name": "actual cost 2,100 kg × £4.80 = £10,080"},
              {"expr": "2000 * 5 - 10080", "equals": "net", "name": "standard cost £10,000 less actual £10,080 = −£80"}])

mk("u07-14", "bus-payback", "bars", "Cumulative cash flow and payback",
   "The £100,000 outlay is still £30,000 short after two years; year 3's £50,000 repays it 0.6 of the way through, so payback is 2.6 years.",
   "Columns of cumulative cash for years 0 to 4: −£100,000, −£70,000, −£30,000, +£20,000, +£40,000. The bars cross zero between years 2 and 3.",
   ["Year 0: outlay −£100,000.", "Year 1: inflow £30,000, cumulative −£70,000.", "Year 2: inflow £40,000, cumulative −£30,000.", "Year 3: inflow £50,000 makes it +£20,000; the £30,000 shortfall needs 0.6 of the year.", "Payback is 2.6 years."],
   terms=["Payback", "£30,000", "£40,000", "£50,000", "£20,000", "2.6 years"],
   kind="columns", prefix="£", suffix="k", range=[-120, 60], series=[{"name": "Cumulative cash flow", "colour": "a1"}],
   categories=[{"label": "Year 0", "values": [{"id": "c0", "v": -100, "colour": "bad"}]}, {"label": "Year 1", "values": [{"id": "c1", "v": -70, "colour": "bad"}]},
               {"label": "Year 2", "values": [{"id": "c2", "v": -30, "colour": "bad"}]}, {"label": "Year 3", "values": [{"id": "c3", "v": 20, "colour": "good"}]}, {"label": "Year 4", "values": [{"id": "c4", "v": 40, "colour": "good"}]}],
   relations=[{"expr": "c0 + 30", "equals": "c1", "name": "year 1: −100 + 30 = −70"}, {"expr": "c1 + 40", "equals": "c2", "name": "year 2: −70 + 40 = −30"},
              {"expr": "c2 + 50", "equals": "c3", "name": "year 3: −30 + 50 = +20"}, {"expr": "c3 + 20", "equals": "c4", "name": "year 4: +20 + 20 = +40"},
              {"expr": "2 + (0 - c2) / 50", "equals": "2.6", "name": "payback = 2 + 30 ÷ 50 = 2.6 years"}])

mk("u07-15", "bus-npv", "bars", "Discounting the £100,000 project at 10%",
   "Each inflow is worth less today: the later it arrives, the more it shrinks. The present values add to £111,520, which beats the £100,000 outlay by £11,520, so NPV is positive.",
   "Columns for years 0 to 4 comparing cash flow with present value at 10%: −100 and −100, then 30 and 27.27, 40 and 33.04, 50 and 37.55, 20 and 13.66, in £ thousand.",
   ["Year 0: outlay £100,000, not discounted.", "Year 1: £30,000 × 0.909 = £27,270.", "Year 2: £40,000 × 0.826 = £33,040.", "Year 3: £50,000 × 0.751 = £37,550.", "Year 4: £20,000 × 0.683 = £13,660.", "Present values total £111,520; NPV = £11,520."],
   terms=["0.909", "0.826", "0.751", "0.683", "£111,520", "£11,520", "NPV"],
   kind="columns", prefix="£", suffix="k", range=[-145, 60], series=[{"name": "Cash flow", "colour": "a4"}, {"name": "Present value at 10%", "colour": "a1"}],
   categories=[{"label": "Year 0", "values": [{"id": "k0", "v": -100, "series": 0}, {"id": "p0", "v": -100, "series": 1}]},
               {"label": "Year 1", "values": [{"id": "k1", "v": 30, "series": 0}, {"id": "p1", "v": 27.27, "series": 1}]},
               {"label": "Year 2", "values": [{"id": "k2", "v": 40, "series": 0}, {"id": "p2", "v": 33.04, "series": 1}]},
               {"label": "Year 3", "values": [{"id": "k3", "v": 50, "series": 0}, {"id": "p3", "v": 37.55, "series": 1}]},
               {"label": "Year 4", "values": [{"id": "k4", "v": 20, "series": 0}, {"id": "p4", "v": 13.66, "series": 1}]}],
   relations=[{"expr": "k1 * 0.909", "equals": "p1", "tol": 0.0005, "name": "year 1 PV = 30 × 0.909"}, {"expr": "k2 * 0.826", "equals": "p2", "tol": 0.0005, "name": "year 2 PV = 40 × 0.826"},
              {"expr": "k3 * 0.751", "equals": "p3", "tol": 0.0005, "name": "year 3 PV = 50 × 0.751"}, {"expr": "k4 * 0.683", "equals": "p4", "tol": 0.0005, "name": "year 4 PV = 20 × 0.683"},
              {"expr": "p1 + p2 + p3 + p4", "equals": "111.52", "tol": 0.0005, "name": "present values total £111,520"},
              {"expr": "p0 + p1 + p2 + p3 + p4", "equals": "11.52", "tol": 0.001, "name": "NPV = 111,520 − 100,000 = £11,520"}])

mk("u07-04", "bus-operating-cash-flow", "bars", "From operating profit to operating cash flow",
   "Profit is not cash. Depreciation is added back because no cash left; money tied up in receivables and inventory is deducted; the rise in payables is added. Here the adjustments cancel out, so operating cash flow equals operating profit: £80,000.",
   "Waterfall from operating profit £80,000: add depreciation £20,000, deduct receivables rise £15,000, add payables rise £5,000, deduct inventory rise £10,000, leaving operating cash flow £80,000.",
   ["Operating profit £80,000; add depreciation £20,000 to get £100,000.", "Receivables rose £15,000: deduct, leaving £85,000.", "Payables rose £5,000: add, giving £90,000.", "Inventory rose £10,000: deduct, leaving operating cash flow of £80,000."],
   terms=["Operating profit", "depreciation", "receivables", "payables", "inventory", "operating cash flow", "£80,000"],
   kind="waterfall", prefix="£", suffix="k", range=[0, 125],
   items=[{"id": "profit", "label": "Operating profit", "short": "Profit", "v": 80, "type": "start"}, {"id": "dep", "label": "Add depreciation", "short": "Deprec.", "v": 20, "type": "delta"},
          {"id": "recv", "label": "Receivables rose", "short": "Receiv.", "v": -15, "type": "delta"}, {"id": "pay", "label": "Payables rose", "short": "Payables", "v": 5, "type": "delta"},
          {"id": "inv", "label": "Inventory rose", "short": "Invent.", "v": -10, "type": "delta"}, {"id": "ocf", "label": "Operating cash flow", "short": "Cash flow", "v": 80, "type": "total"}],
   relations=[{"expr": "profit + dep + recv + pay + inv", "equals": "ocf", "name": "80 + 20 − 15 + 5 − 10 = 80"}, {"expr": "profit + dep + recv", "equals": "85", "name": "after receivables the running total is £85,000"}])

